package com.dynasty.blueprint.boss;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.MobSpawnType;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;
import net.minecraft.world.level.levelgen.structure.Structure;
import net.minecraft.world.phys.*;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.entity.player.PlayerInteractEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import java.util.*;

/** Three bone offerings at real authored altar positions, then central socket; no automatic boss spawn. */
@Mod.EventBusSubscriber(modid="dynasty")
public final class CauldronPits {
    public static boolean loaded(ServerLevel world,BlockPos centre){var b=new AABB(centre).inflate(21,8,21);if(b.minY<world.getMinBuildHeight()||b.maxY>=world.getMaxBuildHeight()||!world.getWorldBorder().isWithinBounds(b))return false;for(int x=net.minecraft.util.Mth.floor(b.minX)>>4;x<=net.minecraft.util.Mth.floor(b.maxX)>>4;x++)for(int z=net.minecraft.util.Mth.floor(b.minZ)>>4;z<=net.minecraft.util.Mth.floor(b.maxZ)>>4;z++)if(!world.hasChunkAt(new BlockPos(x<<4,0,z<<4)))return false;return true;}
    public static boolean summon(ServerLevel world,CauldronPitState.Pit pit){if(world.dimension()!=Level.OVERWORLD||world.getDifficulty()==Difficulty.PEACEFUL||pit.defeated||pit.boss!=null||pit.ritualMask!=7||!loaded(world,pit.centre))return false;var type=CauldronPitContent.CAULDRON.get();var at=Vec3.atBottomCenterOf(pit.centre);var box=type.getDimensions().makeBoundingBox(at);if(!world.noCollision(null,box)||!world.getBlockState(pit.centre.below()).isFaceSturdy(world,pit.centre.below(),Direction.UP))return false;var mob=type.create(world);if(mob==null)return false;mob.moveTo(at.x,at.y,at.z,0,0);mob.bindArena(pit.centre);mob.finalizeSpawn(world,world.getCurrentDifficultyAt(pit.centre),MobSpawnType.EVENT,null,null);if(!world.addFreshEntity(mob))return false;pit.boss=mob.getUUID();CauldronPitState.get(world).setDirty();return true;}
    @SubscribeEvent public static void rightClick(PlayerInteractEvent.RightClickBlock e){if(e.getHand()!=InteractionHand.MAIN_HAND||!(e.getEntity() instanceof ServerPlayer player)||!(e.getLevel() instanceof ServerLevel world)||player.isSpectator()||player.isCreative()||!world.getBlockState(e.getPos()).is(CauldronPitContent.RITUAL.get())||player.distanceToSqr(Vec3.atCenterOf(e.getPos()))>6.5*6.5)return;
        var state=CauldronPitState.get(world);for(var pit:state.pits.values()){if(pit.centre.distSqr(e.getPos())>16*16||pit.defeated||pit.boss!=null)continue;for(int i=0;i<3;i++)if(e.getPos().equals(CauldronPitPiece.altar(pit.centre,i))&&player.getMainHandItem().is(Items.BONE)&&((pit.ritualMask>>i)&1)==0){pit.ritualMask|=1<<i;player.getMainHandItem().shrink(1);state.setDirty();e.setCanceled(true);e.setCancellationResult(InteractionResult.SUCCESS);return;}if(e.getPos().equals(pit.centre.below())&&summon(world,pit)){e.setCanceled(true);e.setCancellationResult(InteractionResult.SUCCESS);return;}}
    }
    @SubscribeEvent public static void leftClick(PlayerInteractEvent.LeftClickBlock e){if(e.getAction()!=PlayerInteractEvent.LeftClickBlock.Action.START||!(e.getEntity() instanceof ServerPlayer p)||!(e.getLevel() instanceof ServerLevel world))return;var state=CauldronPitState.get(world);for(var pit:state.pits.values())if(pit.boss!=null&&!pit.defeated&&pit.centre.distSqr(e.getPos())<21*21&&world.getEntity(pit.boss) instanceof TaoyanCauldron boss&&boss.braceAtPillar(p,e.getPos())){e.setCanceled(true);return;}}
    @SubscribeEvent public static void playerTick(TickEvent.PlayerTickEvent e){if(e.phase!=TickEvent.Phase.END||!(e.player instanceof ServerPlayer p)||p.isSpectator()||p.level().getGameTime()%80!=Math.floorMod(p.getId(),80)||!(p.level() instanceof ServerLevel world)||world.dimension()!=Level.OVERWORLD)return;
        var registry=world.registryAccess().registryOrThrow(Registries.STRUCTURE);var starts=new LinkedHashSet<net.minecraft.world.level.levelgen.structure.StructureStart>();var origin=p.chunkPosition();int references=64;
        for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){var pos=new ChunkPos(origin.x+dx,origin.z+dz);if(!world.hasChunk(pos.x,pos.z))continue;var chunk=world.getChunkSource().getChunk(pos.x,pos.z,net.minecraft.world.level.chunk.ChunkStatus.STRUCTURE_REFERENCES,false);if(chunk==null)continue;chunk.getAllStarts().forEach((type,start)->{if(registry.getKey(type)!=null&&registry.getKey(type).equals(new net.minecraft.resources.ResourceLocation("dynasty","cauldron_pit")))starts.add(start);});for(var entry:chunk.getAllReferences().entrySet())if(new net.minecraft.resources.ResourceLocation("dynasty","cauldron_pit").equals(registry.getKey(entry.getKey())))for(long packed:entry.getValue()){if(references--<=0)break;var owner=new ChunkPos(packed);if(world.hasChunk(owner.x,owner.z)){var c=world.getChunkSource().getChunk(owner.x,owner.z,net.minecraft.world.level.chunk.ChunkStatus.STRUCTURE_STARTS,false);if(c!=null){var start=c.getStartForStructure(entry.getKey());if(start!=null)starts.add(start);}}}}
        var state=CauldronPitState.get(world);for(var start:starts)if(start.isValid()&&start.getBoundingBox().isInside(p.blockPosition()))for(var piece:start.getPieces())if(piece instanceof CauldronPitPiece pit)state.register(pit.centre());
    }
    @SubscribeEvent public static void levelTick(TickEvent.LevelTickEvent e){if(e.phase!=TickEvent.Phase.END||!(e.level instanceof ServerLevel world)||world.getGameTime()%10!=0||world.dimension()!=Level.OVERWORLD)return;var state=CauldronPitState.get(world);int budget=2;for(var pit:state.pits.values())if(pit.defeated&&pit.environmentCursor<2000&&world.players().stream().anyMatch(p->!p.isSpectator()&&pit.centre.distSqr(p.blockPosition())<=48*48)&&loaded(world,pit.centre)){applyEnvironment(world,pit,64);if(--budget<=0)break;}}
    public static void destroyed(TaoyanCauldron boss){if(!(boss.level() instanceof ServerLevel world)||boss.arenaCentre()==null)return;var state=CauldronPitState.get(world);var pit=state.pits.get(boss.arenaCentre().asLong());if(pit!=null&&!pit.defeated&&boss.getUUID().equals(pit.boss)){pit.boss=null;pit.ritualMask=0;state.setDirty();}}
    public static void confirmedDeath(TaoyanCauldron boss){if(!(boss.level() instanceof ServerLevel world)||boss.arenaCentre()==null)return;var state=CauldronPitState.get(world);var pit=state.pits.get(boss.arenaCentre().asLong());if(pit==null||pit.defeated||!boss.getUUID().equals(pit.boss))return;pit.defeated=true;pit.boss=null;pit.environmentCursor=0;state.setDirty();int rewarded=0;for(var player:world.players())if(rewarded<16&&!player.isSpectator()&&!player.isCreative()&&player.isAlive()&&player.distanceToSqr(Vec3.atBottomCenterOf(pit.centre))<=24*24&&state.firstRewarded.add(player.getUUID())){var stack=new ItemStack(CauldronPitContent.CRYSTAL.get());if(!player.addItem(stack))player.drop(stack,false);rewarded++;state.setDirty();}if(loaded(world,pit.centre))applyEnvironment(world,pit,64);}
    public static void applyEnvironment(ServerLevel world,CauldronPitState.Pit pit,int budget){if(!pit.defeated||!loaded(world,pit.centre)||pit.environmentCursor>=2000)return;var edits=new ArrayList<BlockPos>();for(int x=-20;x<=20;x++)for(int z=-20;z<=20;z++)if(x*x+z*z>17*17&&x*x+z*z<=400)for(int y=-5;y<=-2;y++)edits.add(pit.centre.offset(x,y,z));int cursor=pit.environmentCursor;while(budget-->0&&cursor<edits.size()){var pos=edits.get(cursor++);if(world.getBlockState(pos).is(CauldronPitContent.SOUL_OIL.get()))world.setBlock(pos,Blocks.AIR.defaultBlockState(),3);}pit.environmentCursor=cursor;if(cursor>=edits.size()){
        for(int i=0;i<12;i++){var at=CauldronPitPiece.pillar(pit.centre,i).above(5);var s=world.getBlockState(at);if(s.is(Blocks.SOUL_CAMPFIRE))world.setBlock(at,s.setValue(CampfireBlock.LIT,false),3);}
        if(world.getBlockState(pit.centre.below()).is(CauldronPitContent.RITUAL.get())){world.setBlock(pit.centre.below(),Blocks.QUARTZ_BLOCK.defaultBlockState(),3);for(int y=0;y<3;y++)if(world.isEmptyBlock(pit.centre.above(y)))world.setBlock(pit.centre.above(y),Blocks.QUARTZ_PILLAR.defaultBlockState(),3);}
        var door=pit.centre.offset(0,-5,19);for(int y=0;y<2;y++){var at=door.above(y);var s=world.getBlockState(at);if(s.is(Blocks.IRON_DOOR))world.setBlock(at,s.setValue(DoorBlock.OPEN,true),3);}pit.environmentCursor=2000;
    }CauldronPitState.get(world).setDirty();}
    private CauldronPits(){}
}
